<template><main class="ccd-page rewards-page"><ConnectedDemoHeader icon="🎁" title="Community Rewards" subtitle="Reward meaningful participation across every platform"/><section class="ccd-grid ccd-metrics"><ConnectedDemoMetric icon="☆" label="Points Issued" :value="(48250+(demo.reward.granted?100:0)).toLocaleString()" detail="All-time across platforms"/><ConnectedDemoMetric icon="▤" label="Active Reward Rules" value="12" detail="Currently live in demo"/><ConnectedDemoMetric icon="✓" label="Rewards Claimed" value="684" detail="By community members"/><ConnectedDemoMetric icon="♡" label="Positive Actions" value="3,210" detail="Tracked this month"/></section><section class="rewards-top"><section class="ccd-card rule-builder"><header><div><h2>🪄 Reward Rule Builder</h2><p class="ccd-card-sub">Create rules that celebrate positive community actions.</p></div><div><button class="ccd-button" @click="testReward">▷ Test reward</button><button class="ccd-button primary" @click="grantAttendanceReward">Save in demo</button></div></header><div class="rule-flow"><article><small>1　TRIGGER</small><p>What starts this reward?</p><strong>▣ Attend Friday<br>Game Night</strong><span>Event-based trigger</span></article><b>→</b><article><small>2　CONDITIONS</small><p>What must be true?</p><strong>♙ RSVP + verified<br>attendance</strong><span>All conditions must be met</span></article><b>→</b><article><small>3　REWARD</small><p>What is granted?</p><strong>✦ Grant 100<br>Community Points</strong><span>Instant award</span></article></div><div class="rule-options"><article><h3>🏆 Optional Achievement Progress</h3><p>Community Regular</p><div class="ccd-progress"><i :style="{width:demo.achievement.progress/5*100+'%'}"></i></div><small>{{demo.achievement.progress}} / 5 complete</small></article><article><h3>◷ Frequency Limit</h3><p>Once per week per member</p><small>Resets every Monday 12:00 AM PT</small></article></div></section><section class="ccd-card catalogue"><header><div><h2>♧ Reward Catalogue</h2><p class="ccd-card-sub">Offer cosmetics, roles, and experiences.</p></div><select><option>All Categories</option></select></header><div class="catalogue-grid"><article v-for="reward in rewards" :key="reward.id" :class="{selected:demo.selectedRewardId===reward.id}"><div class="reward-art">{{reward.icon}}</div><b>{{reward.name}}</b><small>{{reward.type}}</small><footer><strong>{{reward.points}} pts</strong><span>{{reward.stock}}</span></footer><button class="ccd-button" @click="selectReward(reward.id)">◉ Preview</button></article></div><p class="ccd-card-sub">Demo catalogue · No real-world value · Positive rewards only</p></section></section><section class="rewards-bottom"><section class="ccd-card member-preview"><header><h2>Your Reward Preview <small>(Local Demo)</small></h2><span>Current Balance <b>✦ {{demo.nova.balance.toLocaleString()}}</b></span></header><div class="nova-row"><span>N</span><strong>Nova#1234 <small class="ccd-positive">● Online</small></strong></div><div class="preview-steps"><article :class="{done:demo.event.attended}"><b>▣ Event Triggered</b><p>Attend Friday Game Night</p></article><article :class="{done:demo.reward.granted}"><b>☆ Reward Granted</b><p>+100 Community Points</p></article><article><b>🏆 Achievement Progress</b><p>Community Regular {{demo.achievement.progress}} / 5</p></article></div><div v-if="demo.reward.granted" class="reward-toast">🎉 Nice! Nova received 100 Community Points!</div><div v-else-if="demo.reward.tested" class="test-toast">Test passed · No points issued during preview.</div></section><section class="ccd-card"><h2>Recent Reward Activity</h2><ul class="ccd-list"><li v-for="item in rewardActivity" :key="item.id"><span>{{item.icon}}</span><div><b>{{item.title}}</b><small>{{item.detail}}</small></div><strong class="ccd-positive">{{item.points}}</strong></li></ul><button class="ccd-button wide">View all</button></section><section class="ccd-card"><h2>♢ Fraud &amp; Fairness Safeguards</h2><ul class="ccd-list safeguards"><li v-for="item in safeguards" :key="item[0]"><span>✓</span><div><b>{{item[0]}}</b><small>{{item[1]}}</small></div></li></ul><button class="ccd-button wide">Manage Safeguards</button></section><section class="ccd-card"><h2>☆ Ways to Earn</h2><ul class="ccd-list earn"><li v-for="item in earn" :key="item[1]"><span>{{item[0]}}</span><div><b>{{item[1]}}</b><small>{{item[2]}}</small></div></li></ul><button class="ccd-button wide">Learn more</button></section></section><footer class="ccd-footer-note">This is a demo environment. Points have no cash value, no payments occur, and all activity is simulated for presentation purposes.</footer></main></template>
<script setup>import{computed}from'vue';import ConnectedDemoHeader from'../../connected-demo/ConnectedDemoHeader.vue';import ConnectedDemoMetric from'../../connected-demo/ConnectedDemoMetric.vue';import{connectedDemo as demo,grantAttendanceReward,selectReward,testReward}from'../../connected-demo/connectedDemoState.js';import'../../connected-demo/connectedDemo.css';const rewards=[['nebula','🐾','Nebula Hoodie','Pet Cosmetic',250,'Stock: 15'],['collar','💜','Purple Star Collar','Pet Cosmetic',150,'Stock: 22'],['trail','☄','Respawn Trail','Pet Cosmetic',200,'Unlimited'],['bed','🛸','Cozy Gaming Bed','Pet Cosmetic',300,'Stock: 8'],['role','♢','Discord Role: VIP','Server Role',200,'Unlimited'],['ticket','🎟','Event Ticket','Priority Access',150,'Stock: 50']].map(([id,icon,name,type,points,stock])=>({id,icon,name,type,points,stock}));const rewardActivity=computed(()=>[{id:'nova',icon:'N',title:'Nova#1234',detail:demo.reward.granted?'Friday Game Night attendance':'Reward pending verified attendance',points:demo.reward.granted?'+100 pts':'Pending'},{id:'luna',icon:'L',title:'Luna#5678',detail:'Shared event on Discord',points:'+150 pts'},{id:'pixel',icon:'P',title:'Pixel#2468',detail:'Tournament participation',points:'+200 pts'}]);const safeguards=[['Cooldowns','Limits frequency per user'],['Duplicate Prevention','Blocks repeated claims'],['Manual Review','Flagged activity reviewed'],['Context Validation','Verifies event participation']];const earn=[['▣','Twitch','Watch, chat, and participate'],['☁','Discord','Engage and help the community'],['▣','Events','Attend and participate'],['R','Project Respawn','Special campaigns and activities']]</script>
<style scoped>.rewards-top{display:grid;grid-template-columns:1.1fr 1fr;gap:12px}.rule-builder>header,.catalogue>header,.member-preview>header{display:flex;justify-content:space-between;gap:10px}.rule-builder header button{margin-left:6px}.rule-flow{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:8px}.rule-flow article{display:grid;min-height:165px;padding:14px;border:1px solid #4f347d;border-radius:8px;background:#211449}.rule-flow article:last-of-type{border-color:#17655f;background:#0b3333}.rule-flow article>small{color:#b46fff}.rule-flow article>p{color:#9dabc0}.rule-flow article>strong{padding:12px;border:1px solid #40516d;border-radius:6px;background:#101b31}.rule-flow article>span{align-self:end;color:#9aa8bc;font-size:12px}.rule-flow>b{font-size:22px}.rule-options{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.rule-options article{padding:12px;border:1px solid #344a69;border-radius:7px}.catalogue select{height:36px;padding:0 8px;border:1px solid #30445f;border-radius:6px;background:#09162a;color:#fff}.catalogue-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.catalogue-grid article{display:grid;padding:9px;border:1px solid #2b405d;border-radius:7px;text-align:center}.catalogue-grid article.selected{border-color:#a64df0;box-shadow:0 0 20px rgba(166,77,240,.24)}.catalogue-grid small{color:#9ba8ba}.reward-art{display:grid;height:75px;place-items:center;font-size:48px;background:radial-gradient(circle,#25235b,transparent 68%)}.catalogue-grid footer{display:flex;justify-content:space-between;margin:5px 0;font-size:11px}.catalogue-grid footer strong{color:#facc15}.catalogue-grid .ccd-button{min-height:32px;padding:4px}.rewards-bottom{display:grid;grid-template-columns:1.45fr .9fr .9fr .9fr;gap:12px;margin-top:12px}.member-preview header small{color:#b96cff}.member-preview header span{color:#9ba9bc}.member-preview header span b{display:block;color:#d5a6ff;font-size:22px}.nova-row{display:flex;align-items:center;gap:10px;margin:10px 0}.nova-row>span{display:grid;width:48px;height:48px;place-items:center;border:2px solid #a54ce8;border-radius:50%;background:#3c2365}.nova-row small{display:block}.preview-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.preview-steps article{padding:10px;border:1px solid #304660;border-radius:6px}.preview-steps article.done{border-color:#3eaf72}.preview-steps p{color:#aab5c7;font-size:11px}.reward-toast,.test-toast{margin-top:10px;padding:13px;border:1px solid #7c3aed;border-radius:7px;background:#251348;text-align:center;color:#55efcd}.test-toast{color:#67e8f9}.wide{width:100%;margin-top:10px}.safeguards>li>span{display:grid;width:24px;height:24px;place-items:center;border:1px solid #28a36d;border-radius:50%;color:#4ade80}.earn>li>span{display:grid;width:34px;height:34px;place-items:center;border-radius:7px;background:#31206b;font-size:20px}@media(max-width:1500px){.rewards-bottom{grid-template-columns:1fr 1fr}.catalogue-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:1100px){.rewards-top{grid-template-columns:1fr}.catalogue-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.rule-flow{grid-template-columns:1fr}.rule-flow>b{transform:rotate(90deg);text-align:center}.rule-options,.rewards-bottom,.preview-steps{grid-template-columns:1fr}}</style>
